let () =
  match
    Vhs.tape
      ~settings:
        [
          Shell Bash;
          Font_size 18;
          Width 1000;
          Height 460;
          Theme "Builtin Dark";
          Padding 20;
          Typing_speed (Ms 20);
        ]
      ~outputs:[ "examples/display/display.gif" ]
      [
        Vhs.raw
          "# Generated by tape.ml: a build whose running steps are redrawn in \
           place.";
        Vhs.raw {|Require "dune"|};
        Vhs.hidden
          [
            Vhs.type' "dune build examples/display/main.exe && clear\n";
            Vhs.wait ~timeout:(Ms 300_000) Prompt;
          ];
        Vhs.type' "dune exec examples/display/main.exe\n";
        Vhs.wait ~timeout:(Ms 60_000) (Screen "build complete");
        Vhs.sleep (Ms 2000);
      ]
  with
  | Ok t -> print_string (Vhs.to_string t)
  | Error e ->
      prerr_endline e;
      exit 1
